from pathlib import Path
import json
root=Path(__file__).parent
slides=[]
def slide(id,title,group,minutes,src,body,notes):
 slides.append(dict(id=id,title=title,group=group,minutes=minutes,src=src,body=body,notes=notes))
def plot(id,caption='Координатные оси x и y; одна клетка соответствует одной единице.'):
 return f'<div class="plot"><div id="{id}"></div><p class="plot-caption">{caption}</p></div>'
def slider(key,label,lo,hi,value,step=1):
 return f'<label class="slider"><span>{label}</span><input type="range" data-param="{key}" min="{lo}" max="{hi}" step="{step}" value="{value}" aria-label="Коэффициент {label}"><output id="out-{key}">{value}</output></label>'
def btn(label,action,extra=''):return f'<button {extra} data-action="{action}">{label}</button>'
def ref(name,label='Все правила и пояснения'):return f'<button data-book="{name}">{label} ↗</button>'
slide('atlas','Функции. От прямой к параболе','Карта урока',2,'Обзор разделов учебника', '''<div class="herohead"><div><h1>Один аргумент.<br>Целый мир <span class="blue">функций.</span></h1></div><p class="lead">Выбери график — открой его устройство, свойства и правила.</p></div><div class="badges"><span>10 класс</span><span>15 слайдов</span><span>45 минут</span><span>Графики можно исследовать</span></div><div class="atlas" id="atlas-grid"></div><p class="small">Маршрут урока: язык функций → прямая → парабола → другие виды → практика. К этой карте можно вернуться кнопкой «Карта».</p>''','0:00–2:00. Спросите: что общего у шести рисунков? Покажите переход по параболе и вернитесь на карту. Для последовательного урока нажмите «Далее». Объясните, что графики — разные способы видеть зависимость y от x.')
slide('language','Что делает функцию функцией?','Общий язык',2,'с. 88–91, 93',f'''<h2>Каждому x — <span class="blue">ровно один y.</span></h2><div class="layout"><div class="textcol"><div class="formula">f: A → B, y = f(x)</div><p><b>x</b> — аргумент; <b>y</b> — значение.</p><p><b>D(f) = A</b> — допустимые x.<br><b>E(f) = f(A)</b> — получаемые y.</p><div class="rule">Важно: E(f) ⊆ B. Не путай допустимые и получаемые значения.</div>{slider('point','x',-3,3,1,.25)}<div id="point-readout" class="result"></div><div class="controls">{btn('Парабола','relation:parabola')}{btn('Окружность','relation:circle')}</div></div>{plot('plot-language','Двигай вертикальную линию: для функции у каждого допустимого x только одно пересечение.')}</div>''','2:00–4:00. Проведите вертикальную линию при x=1. На параболе одно значение, на окружности два. Обязательно различайте B и E(f). Способы задания, образ/прообраз, равенство функций и операции доступны в справочнике.')
slide('properties','Как читать любой график','Общий язык',3,'с. 92–98',f'''<h2>У графика есть <span class="blue">паспорт.</span></h2><p class="lead">Выбери свойство. График покажет, что именно нужно искать.</p><div class="layout"><div class="textcol"><div class="property-grid" id="property-buttons"></div><div class="result" id="property-text" aria-live="polite"></div><p class="small">Исследуем f(x) = x² − 4. Одно свойство не заменяет остальные.</p></div>{plot('plot-properties')}</div>''','4:00–7:00. Обязательные клики: D и E, нули/знаки, монотонность, экстремум. Затем коротко чётность. Периодичность и обратимость оставьте как вопросы: повторяется ли парабола? можно ли по y однозначно восстановить x? Все строгие определения — в справочнике.')
slide('linear-lab','Прямая: смысл a и b','Первая степень · 1/3',2,'с. 102–103',f'''<h2>Наклон задаёт a.<br>Высоту на оси y — b.</h2><div class="layout"><div class="textcol"><div class="formula blue" id="linear-formula"></div>{slider('la','a',-3,3,1,.5)}{slider('lb','b',-4,4,1,.5)}<div class="result" id="linear-readout"></div><p>a = Δy / Δx. Если x увеличивается на 1, значение y меняется на a.</p><div class="controls">{btn('Прямая пропорциональность: b = 0','linear-origin')}{btn('Сброс','reset:linear')}</div></div>{plot('plot-linear')}</div>''','7:00–9:00. Попросите предсказать график до перемещения a. Проверьте a>0, a<0, a=0. Последний случай — постоянная функция, не функция I степени. Затем установите b=0: прямая проходит через начало координат.')
slide('linear-properties','Все свойства прямой','Первая степень · 2/3',3,'с. 93–98, 102–103',f'''<h2>Один нуль. Один наклон.<br><span class="blue">Никаких поворотов.</span></h2><div class="layout"><div class="textcol"><div class="controls">{btn('a > 0: 2x − 2','linecase:up')}{btn('a < 0: −2x + 2','linecase:down')}</div><div id="line-properties"></div><div class="rule">При a ≠ 0: D(f) = E(f) = ℝ. Нет максимума и минимума; функция не ограничена ни сверху, ни снизу.</div><p class="small">Непериодическая. Обратима на ℝ. Нечётная только при b = 0; при b ≠ 0 — ни чётная, ни нечётная.</p></div>{plot('plot-lineprops','Цветные части графика показывают знак: синий — положительный, оранжевый — отрицательный.')}</div>''','9:00–12:00. Для двух функций нуль одинаков: x=1. Но знак слева и справа меняется местами. Подчеркните: нуль — число x, точка пересечения — (x;0). Обратная функция f⁻¹(x)=(x−b)/a, не 1/f(x).')
slide('linear-solve','Уравнение, неравенство, пересечение','Первая степень · 3/3',3,'с. 103–109',f'''<h2>Решение — это <span class="blue">место на графике.</span></h2><div class="layout"><div class="textcol"><div class="controls">{btn('Нуль','linear-task:zero')}{btn('Знак','linear-task:sign')}{btn('Две прямые','linear-task:cross')}</div><div id="linear-task-text"></div><div class="rule">При делении неравенства на отрицательное число знак неравенства меняется.</div><p class="small">Система = «и» = пересечение решений.<br>Совокупность = «или» = объединение решений.</p></div>{plot('plot-linearsolve')}</div>''','12:00–15:00. Решите 2x−2=0 и −2x+2≥0. Спросите, почему ответ x≤1. Затем решите 2x−2=−x+4: x=2, y=2. Для двух прямых также возможны параллельность и совпадение; эти случаи указаны в справочнике.')
slide('quadratic-lab','Парабола: смысл коэффициентов','Вторая степень · 1/6',2,'с. 113',f'''<h2>Добавляем x².<br>Прямая становится <span class="accent">параболой.</span></h2><div class="layout"><div class="textcol"><div class="formula accent" id="quadratic-formula"></div>{slider('qa','a',-2,2,1,.5)}{slider('qb','b',-4,4,-2,.5)}{slider('qc','c',-3,3,-1,.5)}<div class="result" id="quadratic-readout"></div><div class="controls">{btn('Сброс','reset:quadratic')}{btn('Только график','toggle-copy')}</div></div>{plot('plot-quadratic','Изменение b обычно сдвигает и ось симметрии, и высоту вершины. Это не простой горизонтальный перенос.')}</div>''','15:00–17:00. Покажите a>0, a<0 и a=0. В последнем случае функция уже не II степени. При одинаковом расстоянии от вершины большее |a| даёт большее отклонение по вертикали. c — ордината пересечения с Oy, а не обязательно высота вершины.')
slide('vertex','Вершина и преобразования','Вторая степень · 2/6',3,'с. 94, 96, 113; выделение квадрата',f'''<h2>Вся парабола — вокруг <span class="accent">одной точки.</span></h2><div class="layout"><div class="textcol"><div class="formula">f(x) = a(x − h)² + k</div><p><b>Вершина V(h; k).</b> Ось симметрии: x = h.</p><div class="rule orange"><span class="math">h = −b/(2a), k = f(h) = −Δ/(4a)</span><br>Δ = b² − 4ac, a ≠ 0.</div>{slider('vh','h',-3,3,1,.5)}{slider('vk','k',-3,3,-2,.5)}<div id="vertex-readout" class="result"></div><div class="controls">{btn('a = 1','vertex-a:1')}{btn('a = −1','vertex-a:-1')}{btn('Сброс','reset:vertex')}</div></div>{plot('plot-vertex','Серая кривая — y = x². Цветная — преобразованная парабола.')}</div>''','17:00–20:00. Начните с x², затем h=1 и k=−2. Спросите, почему x−1 означает перенос вправо. Покажите пары точек h−1 и h+1. В справочнике — выделение полного квадрата и перевод между тремя формами записи.')
slide('roots','Дискриминант и нули','Вторая степень · 3/6',3,'с. 113–114',f'''<h2>Сколько раз парабола<br>встретит <span class="accent">ось x?</span></h2><div class="layout"><div class="textcol"><div class="formula">Δ = b² − 4ac</div><div class="controls">{btn('Δ > 0','disc:positive')}{btn('Δ = 0','disc:zero')}{btn('Δ < 0','disc:negative')}</div><div class="controls">{btn('Ветви вверх','disc-sign:1')}{btn('Ветви вниз','disc-sign:-1')}</div><div id="disc-readout" class="result"></div><p class="math">x = (−b ± √Δ) / (2a), если Δ ≥ 0.</p><p class="small">Δ &gt; 0: два различных корня.<br>Δ = 0: один корень кратности 2.<br>Δ &lt; 0: действительных корней нет.</p></div>{plot('plot-roots')}</div>''','20:00–23:00. Последовательно покажите три значения Δ для ветвей вверх, затем вниз. Всего шесть случаев из рисунка 7.3. При a<0 корень с минусом перед √Δ не обязательно меньший: для таблицы знаков всегда упорядочиваем корни r₁<r₂.')
slide('variation','Возрастание, экстремум, значения','Вторая степень · 4/6',3,'с. 94, 96–98, 113',f'''<h2>До вершины — одно движение.<br>После — <span class="accent">обратное.</span></h2><div class="layout"><div class="textcol"><div class="controls">{btn('a > 0: минимум','variation:1')}{btn('a < 0: максимум','variation:-1')}</div>{slider('vx','x',-2,4,0,.25)}<div class="result" id="variation-readout"></div><div id="variation-properties"></div><p class="small">На всей ℝ парабола не монотонна и не обратима. На каждой отдельной ветви — строго монотонна и обратима на своё множество значений.</p></div>{plot('plot-variation','Двигай точку слева направо. Вершина разделяет промежутки монотонности.')}</div>''','23:00–26:00. Различайте точку экстремума h и значение экстремума k. Двигайте x, наблюдайте убывание и возрастание. При a>0 есть нижняя граница, но нет верхней; при a<0 наоборот. Обсудите чётность: общая парабола чётна только при b=0, хотя ось симметрии есть всегда.')
slide('quadratic-signs','Знаки и квадратные неравенства','Вторая степень · 5/6',3,'с. 117–118',f'''<h2>Знак функции читается<br><span class="accent">выше и ниже оси x.</span></h2><div class="layout"><div class="textcol"><div class="controls">{btn('Δ > 0','sign-disc:positive')}{btn('Δ = 0','sign-disc:zero')}{btn('Δ < 0','sign-disc:negative')}</div><div class="controls">{btn('a > 0','sign-a:1')}{btn('a < 0','sign-a:-1')}</div><label>Решить <select id="sign-op" aria-label="Знак квадратного неравенства"><option value=">">f(x) > 0</option><option value=">=">f(x) ≥ 0</option><option value="<">f(x) &lt; 0</option><option value="<=">f(x) ≤ 0</option></select></label><div class="result" id="sign-result" aria-live="polite"></div><p>При двух корнях: <b>снаружи знак a, между корнями — противоположный.</b></p><p class="small">При ≥ или ≤ подходящие нули включаем. При двойном корне знак через него не меняется.</p></div>{plot('plot-signs','Толстый участок на оси x — множество решений. Закрашенные точки входят в ответ, пустые — нет.')}</div>''','26:00–29:00. Основной пример x²−2x−3≤0 даёт [−1;3]. Покажите переключение на строгое неравенство. Затем Δ=0: для (x−1)²≤0 остаётся единственная точка, а при <0 решений нет. Все 24 сочетания доступны для самостоятельного повторения.')
slide('build','Собираем исследование целиком','Вторая степень · 6/6',3,'с. 113–114, 117–123',f'''<h2>Пять шагов от формулы<br>до <span class="accent">полного графика.</span></h2><div class="layout"><div class="textcol"><div class="formula">f(x) = x² − 4x + 3</div><ol class="steps" id="build-steps"><li>D(f), коэффициенты, ветви</li><li>Вершина и ось симметрии</li><li>Нули и пересечение с Oy</li><li>Симметричные точки и график</li><li>Свойства и знак</li></ol><div id="build-detail" class="step-detail"></div><div class="controls">{btn('← Шаг','build-prev')}{btn('Следующий шаг →','build-next','class="primary"')}{btn('Сначала','build-reset')}</div></div>{plot('plot-build')}</div>''','29:00–32:00. Открывайте по одному шагу. Корни 1 и 3 проверяются по Виету: сумма 4, произведение 3. Вершина (2;−1), Oy: (0;3). Завершите выводом об E(f), монотонности и знаках. В справочнике — Виет, обратная теорема, неполные уравнения, параметры, модуль, системы и метод интервалов как дополнительное чтение.')
slide('others','За пределами прямой и параболы','Другие функции',3,'с. 90, 94–95, 128–129, 139, 147–148',f'''<h2>Один язык.<br><span class="blue">Разные семейства.</span></h2><div class="stage-tabs" id="other-tabs"></div><div class="layout"><div class="textcol"><div id="other-description"></div><div class="controls">{btn('Сравнить с x²','other-compare')}</div></div>{plot('plot-others','Выбери семейство: меняются и график, и его свойства.')}</div>''','32:00–35:00. Основной обзор: √x, 1/x, |x|, x³. Если класс готов — показательная и логарифмическая. Подчеркните область определения. Остальные вкладки и полный справочник предназначены для изучения после урока, не для чтения всех свойств вслух за три минуты.')
slide('practice-linear','Практика · первая степень','Практика · 1/2',5,'Авторские задания по с. 102–109','''<h2>Сначала реши.<br>Потом <span class="blue">проверь себя.</span></h2><p class="lead">Работайте в парах. Объясняйте выбор через наклон, нуль и знак.</p><div class="questions" id="linear-questions"></div><div class="controls"><button data-action="quiz-reset">Пройти заново</button><span class="score" id="linear-score">Решено: 0 из 3</span></div>''','35:00–40:00. 2 минуты — самостоятельное решение, 2 — сравнение в парах, 1 — разбор. Не показывайте ответы до обсуждения. После неверного выбора появляется объяснение и можно ответить ещё раз. Счётчик показывает число найденных верных ответов, а не оценку первой попытки.')
slide('practice-quadratic','Практика · вторая степень','Практика · 2/2',5,'Авторские задания по с. 113–118',f'''<h2>Теперь — <span class="accent">полное исследование.</span></h2><div class="layout"><div class="textcol"><div class="formula">g(x) = −x² + 4x + 5</div><p>Найди вершину, корни и реши g(x) ≥ 0.</p><div class="practice-fields"><label class="field">x вершины<input id="answer-h" inputmode="decimal" placeholder="Число" autocomplete="off"></label><label class="field">y вершины<input id="answer-k" inputmode="decimal" placeholder="Число" autocomplete="off"></label><label class="field">Меньший корень<input id="answer-r1" inputmode="decimal" placeholder="Число" autocomplete="off"></label><label class="field">Больший корень<input id="answer-r2" inputmode="decimal" placeholder="Число" autocomplete="off"></label></div><label class="field" style="margin-top:12px">g(x) ≥ 0: промежуток<input id="answer-interval" placeholder="Например: [0; 2]" autocomplete="off"></label><div class="controls">{btn('Проверить','check-quadratic','class="primary"')}{btn('Решение по шагам','practice-solution')}{btn('Сброс','practice-reset')}</div><div id="practice-feedback" class="feedback" aria-live="polite"></div></div>{plot('plot-practice','График и ответы откроются по кнопке «Решение по шагам» или после полностью верного ответа.')}</div>''','40:00–45:00. 3 минуты — индивидуальное решение, 1 — проверка, 1 — вывод. Ответ: V(2;9), корни −1 и 5, g≥0 на [−1;5]. Дополнительный устный вопрос: где возрастает функция? На (−∞;2]. Exit ticket: «Что определяет знак a, а что — знак Δ?»')
assert len(slides)==15 and sum(s['minutes'] for s in slides)==45
shell='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f6f5f0"><meta name="description" content="Интерактивный урок о функциях для 10 класса. 15 слайдов, 45 минут, графики и практика."><title>Функции · от прямой к параболе</title><style>__CSS__</style></head><body><header><a class="brand" href="#atlas">ƒ <b>АТЛАС</b></a><div class="toolbar"><button data-action="toc">Слайды</button><button data-action="mode" id="mode-button">Режим чтения</button><button data-action="notes" class="desktop">Заметки · N</button><button data-action="sources" class="desktop">Источники</button><button data-action="fullscreen" aria-label="Полный экран">⛶</button><button data-action="timer" id="timer-button" class="timer" aria-label="Запустить таймер урока">▶ 45:00</button></div></header><noscript><div class="noscript">Включите JavaScript для графиков, переходов и проверки заданий.</div><style>.slide{display:block}</style></noscript><main>__SLIDES__</main><footer><div class="navleft"><button data-go="atlas">Карта</button><span id="counter" class="count">01 / 15</span></div><nav class="dots" aria-label="Перейти к слайду">__DOTS__</nav><div class="navright"><span class="nextlabel" id="next-label"></span><button data-action="prev" aria-label="Предыдущий слайд">←</button><button data-action="next" class="primary" aria-label="Следующий слайд">Далее →</button></div></footer><dialog id="panel"><div class="dialoghead"><h2 id="panel-title"></h2><button data-action="close" aria-label="Закрыть окно">✕</button></div><div class="dialogbody" id="panel-body"></div></dialog><div class="toast" id="toast" role="status"></div><div class="live" aria-live="polite" id="announce"></div><script>const SLIDES=__DATA__;__BOOK__;__JS__</script></body></html>'''
sections=[]
for i,s in enumerate(slides):
 key=['atlas','language','properties','linear','linear','equations','quadratic','vertex','roots','variation','signs','methods','others','practice','practice'][i]
 sections.append(f'<section id="{s["id"]}" class="slide {"current" if i==0 else ""}" aria-label="Слайд {i+1}. {s["title"]}"><div class="kicker"><span>{s["group"]}</span><span class="time">{s["minutes"]} мин · {i+1:02d} / 15</span></div>{s["body"]}<div class="source"><span>Учебник: {s["src"]}</span>{ref(key)}</div></section>')
dots=''.join(f'<button data-go="{s["id"]}" class="{"linear" if 3<=i<=5 else "quad" if 6<=i<=11 else ""}" aria-label="Слайд {i+1}: {s["title"]}" title="{i+1}. {s["title"]}"></button>' for i,s in enumerate(slides))
html=shell.replace('__CSS__',(root/'dist/style.css').read_text()).replace('__SLIDES__',''.join(sections)).replace('__DOTS__',dots).replace('__DATA__',json.dumps([{k:v for k,v in s.items() if k!='body'} for s in slides],ensure_ascii=False)).replace('__BOOK__',(root/'book.js').read_text()).replace('__JS__',(root/'app.js').read_text())
(root/'dist/index.html').write_text(html)
(root/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2))
print('Built 15 slides / 45 minutes:',len(html),'characters')
